import {
  AccountingSourceType,
  BusinessEventStatus,
  CloseChecklistStatus,
  CloseFindingStatus,
  CloseRunStatus,
  JournalEntryStatus,
  LedgerPostingBatchStatus,
  PaymentExceptionStatus,
  PaymentTransactionState,
  Prisma,
  ReconciliationRunStatus,
  SuspenseStatus,
} from "@prisma/client"

import { db } from "@/prisma/db"
import { NotFoundError } from "@/services/_shared/action-errors"
import { MANUAL_ALLOCATION_STATUSES } from "@/services/reconciliation/manual-match-evidence"

import { createProofTrailBlocker } from "./evidence-blockers.service"
import type {
  EvidenceGrade,
  ProofTrailBlocker,
  ProofTrailEdge,
  ProofTrailInput,
  ProofTrailNextAction,
  ProofTrailNode,
  ProofTrailRedaction,
  ProofTrailResult,
} from "./evidence-contracts"
import {
  computeCloseRunEvidenceGrade,
  computeJournalEntryEvidenceGrade,
  computePaymentTransactionEvidenceGrade,
  computeReconciliationRunEvidenceGrade,
} from "./evidence-grade.service"
import { applyProofTrailRedactions, createProofTrailRedaction } from "./evidence-redaction.service"

type DbClient = typeof db | Prisma.TransactionClient

const OPEN_PAYMENT_EXCEPTION_STATUSES: readonly PaymentExceptionStatus[] = [
  PaymentExceptionStatus.OPEN,
  PaymentExceptionStatus.ASSIGNED,
  PaymentExceptionStatus.ACKNOWLEDGED,
  PaymentExceptionStatus.ESCALATED,
  PaymentExceptionStatus.RESOLUTION_PROPOSED,
  PaymentExceptionStatus.REOPENED,
]

const OPEN_SUSPENSE_STATUSES: readonly SuspenseStatus[] = [
  SuspenseStatus.OPEN,
  SuspenseStatus.ASSIGNED,
  SuspenseStatus.IN_REVIEW,
  SuspenseStatus.POSTED_TO_SUSPENSE,
  SuspenseStatus.RESOLUTION_PROPOSED,
  SuspenseStatus.REOPENED,
]

const ACCOUNTING_SOURCE_TYPES = new Set<string>(Object.values(AccountingSourceType))

function accountingSourceType(value: string | null | undefined): AccountingSourceType | null {
  if (!value) return null
  return ACCOUNTING_SOURCE_TYPES.has(value) ? (value as AccountingSourceType) : null
}

const OPEN_CLOSE_FINDING_STATUSES: readonly CloseFindingStatus[] = [
  CloseFindingStatus.OPEN,
  CloseFindingStatus.ASSIGNED,
  CloseFindingStatus.IN_REVIEW,
  CloseFindingStatus.REOPENED,
]

function node(input: ProofTrailNode): ProofTrailNode {
  return input
}

function edge(input: ProofTrailEdge): ProofTrailEdge {
  return input
}

function nextAction(input: ProofTrailNextAction): ProofTrailNextAction {
  return input
}

function freshnessFor(blockers: ProofTrailBlocker[], availableNodes: ProofTrailNode[]) {
  if (blockers.some((blocker) => blocker.severity === "critical" || blocker.severity === "high")) {
    return "blocked" as const
  }
  if (availableNodes.some((entry) => !entry.available)) return "partial" as const
  return "fresh" as const
}

function sourceModules(nodes: ProofTrailNode[]) {
  return Array.from(new Set(nodes.map((entry) => entry.moduleSlug))).sort()
}

function money(value: Prisma.Decimal | number | string | null | undefined) {
  if (value === null || value === undefined) return "0.00"
  return new Prisma.Decimal(value).toDecimalPlaces(2).toFixed(2)
}

function failedEventBlockers(events: Array<{ id: string; status: BusinessEventStatus; failureMessage: string | null }>) {
  return events
    .filter((event) => event.status === BusinessEventStatus.FAILED || event.status === BusinessEventStatus.REJECTED)
    .map((event) =>
      createProofTrailBlocker({
        id: `business-event-${event.id}`,
        severity: "high",
        gate: "events.business-event",
        title: "Business event failed",
        detail: event.failureMessage || `Business event ${event.id} did not apply successfully.`,
        sourceTables: ["business_events"],
        nextAction: "Review the failed business event before trusting this record.",
      }),
    )
}

// Display samples are bounded; assurance checks must cover every related record.
function severitySummary(groups: Array<{ severity: string; _count: { _all: number } }>) {
  return {
    count: groups.reduce((total, group) => total + group._count._all, 0),
    high: groups.some((group) => group._count._all > 0 && (group.severity === "HIGH" || group.severity === "CRITICAL")),
  }
}

async function paymentBlockerSummary(client: DbClient, scope: {
  organizationId: string
  reconciliationRunId?: string
  paymentTransactionId?: string
}) {
  const [exceptions, suspense] = await Promise.all([
    client.paymentException.groupBy({
      by: ["severity"], where: { ...scope, status: { in: [...OPEN_PAYMENT_EXCEPTION_STATUSES] } }, _count: { _all: true },
    }),
    client.suspenseItem.groupBy({
      by: ["severity"], where: { ...scope, status: { in: [...OPEN_SUSPENSE_STATUSES] } }, _count: { _all: true },
    }),
  ])
  return { exceptions: severitySummary(exceptions), suspense: severitySummary(suspense) }
}

async function completeEventBlockers(client: DbClient, scope: {
  organizationId: string
  sourceType: AccountingSourceType
  sourceId: string
}, events: Array<{ id: string; status: BusinessEventStatus; failureMessage: string | null }>) {
  const blockers = failedEventBlockers(events)
  const undisplayedCount = await client.businessEvent.count({
    where: {
      ...scope,
      status: { in: [BusinessEventStatus.FAILED, BusinessEventStatus.REJECTED] },
      id: { notIn: events.map((event) => event.id) },
    },
  })
  if (undisplayedCount > 0) blockers.push(createProofTrailBlocker({
    id: "business-events-outside-display",
    severity: "high",
    gate: "events.business-event",
    title: "Additional business events failed",
    detail: `${undisplayedCount} failed or rejected business event(s) are outside the displayed evidence sample.`,
    sourceTables: ["business_events"],
    nextAction: "Review the failed business events before trusting this record.",
  }))
  return blockers
}

async function auditSensitiveAccess(
  client: DbClient,
  result: ProofTrailResult,
  actorId?: string | null,
) {
  if (!actorId || !result.audit.sensitiveAccess) return result

  await client.auditLog.create({
    data: {
      entityType: "EvidenceProofTrail",
      entityId: `${result.subjectType}:${result.subjectId}`,
      action: "EVIDENCE_PROOF_TRAIL_VIEWED",
      userId: actorId,
      organizationId: result.organizationId,
      changes: {
        evidenceGrade: result.evidenceGrade,
        subjectType: result.subjectType,
        sourceModules: result.sourceModules,
        redactionCount: result.redactions.length,
      },
    },
  })

  return {
    ...result,
    audit: {
      ...result.audit,
      accessLogged: true,
    },
  }
}

async function buildJournalEntryProofTrail(input: ProofTrailInput, client: DbClient) {
  const entry = await client.journalEntry.findFirst({
    where: { id: input.subjectId, organizationId: input.organizationId },
    include: {
      journal: { select: { id: true, code: true, nameEn: true, nameFr: true } },
      period: { select: { id: true, name: true, status: true } },
      postingBatch: {
        select: {
          id: true,
          sourceType: true,
          sourceId: true,
          postingPurpose: true,
          status: true,
          errorMessage: true,
          postedAt: true,
        },
      },
      sourceLinks: {
        include: {
          postingBatch: {
            select: {
              id: true,
              status: true,
              sourceType: true,
              sourceId: true,
              postingPurpose: true,
            },
          },
        },
        orderBy: { createdAt: "asc" },
      },
      auditEvents: {
        select: {
          id: true,
          action: true,
          resourceType: true,
          resourceId: true,
          message: true,
          createdAt: true,
        },
        orderBy: { createdAt: "desc" },
        take: 10,
      },
    },
  })

  if (!entry) throw new NotFoundError("Journal entry proof subject not found")

  const events = entry.sourceType && entry.sourceId
    ? await client.businessEvent.findMany({
        where: {
          organizationId: input.organizationId,
          sourceType: entry.sourceType,
          sourceId: entry.sourceId,
        },
        select: { id: true, status: true, eventType: true, failureMessage: true },
        orderBy: { recordedAt: "desc" },
        take: 10,
      })
    : []

  const blockers: ProofTrailBlocker[] = entry.sourceType && entry.sourceId
    ? await completeEventBlockers(client, { organizationId: input.organizationId, sourceType: entry.sourceType, sourceId: entry.sourceId }, events)
    : []

  if (entry.status === JournalEntryStatus.VOIDED) {
    blockers.push(
      createProofTrailBlocker({
        id: "journal-entry-voided",
        severity: "critical",
        gate: "accounting.journal.status",
        title: "Journal entry is voided",
        detail: "Voided journal entries cannot be used as trusted accounting proof.",
        sourceTables: ["journal_entries"],
      }),
    )
  }

  if (
    (entry.status === JournalEntryStatus.POSTED || entry.status === JournalEntryStatus.REVERSED) &&
    entry.sourceLinks.length === 0
  ) {
    blockers.push(
      createProofTrailBlocker({
        id: "journal-entry-source-link-missing",
        severity: "high",
        gate: "accounting.source-link",
        title: "Accounting source link is missing",
        detail: "Posted journal entries need source-link evidence before they can support cross-module proof.",
        sourceTables: ["accounting_source_links", "journal_entries"],
        nextAction: "Attach or backfill the accounting source link for this journal entry.",
      }),
    )
  }

  if (entry.postingBatch?.status === LedgerPostingBatchStatus.FAILED) {
    blockers.push(
      createProofTrailBlocker({
        id: "journal-entry-posting-batch-failed",
        severity: "critical",
        gate: "accounting.posting-batch",
        title: "Posting batch failed",
        detail: entry.postingBatch.errorMessage || "The linked ledger posting batch failed.",
        sourceTables: ["ledger_posting_batches"],
      }),
    )
  }

  const decision = computeJournalEntryEvidenceGrade({
    status: entry.status,
    postingBatchStatus: entry.postingBatch?.status,
    sourceLinkCount: entry.sourceLinks.length,
    blockers,
  })

  const subjectNodeId = "journal-entry"
  const nodes: ProofTrailNode[] = [
    node({
      id: subjectNodeId,
      nodeType: "journal.entry",
      nodeId: entry.id,
      label: `Journal entry ${entry.entryNumber}`,
      moduleSlug: "accounting",
      evidenceGrade: decision.grade,
      sourceTable: "journal_entries",
      available: true,
      redacted: false,
      metadata: {
        status: entry.status,
        journal: entry.journal.code,
        period: entry.period.name,
        entryDate: entry.entryDate.toISOString(),
      },
    }),
  ]
  const edges: ProofTrailEdge[] = []

  if (entry.postingBatch) {
    nodes.push(
      node({
        id: "posting-batch",
        nodeType: "ledger.posting.batch",
        nodeId: entry.postingBatch.id,
        label: `Posting batch ${entry.postingBatch.postingPurpose}`,
        moduleSlug: "accounting",
        evidenceGrade: entry.postingBatch.status === LedgerPostingBatchStatus.POSTED ? "posted" : "raw",
        sourceTable: "ledger_posting_batches",
        available: entry.postingBatch.status !== LedgerPostingBatchStatus.FAILED,
        redacted: false,
        metadata: {
          status: entry.postingBatch.status,
          sourceType: entry.postingBatch.sourceType,
          postedAt: entry.postingBatch.postedAt?.toISOString() ?? null,
        },
      }),
    )
    edges.push(edge({
      fromNodeId: "posting-batch",
      toNodeId: subjectNodeId,
      edgeType: "posts_to",
      label: "Posts journal entry",
      evidenceGrade: entry.postingBatch.status === LedgerPostingBatchStatus.POSTED ? "posted" : "raw",
    }))
  }

  entry.sourceLinks.forEach((link, index) => {
    const linkNodeId = `source-link-${index + 1}`
    nodes.push(
      node({
        id: linkNodeId,
        nodeType: "accounting.source_link",
        nodeId: link.id,
        label: link.sourceNumber || `${link.sourceType}/${link.sourceId}`,
        moduleSlug: "accounting",
        evidenceGrade: link.postingBatch.status === LedgerPostingBatchStatus.POSTED ? "posted" : "operational",
        sourceTable: "accounting_source_links",
        available: true,
        redacted: false,
        metadata: {
          sourceType: link.sourceType,
          sourceDate: link.sourceDate?.toISOString() ?? null,
        },
      }),
    )
    edges.push(edge({
      fromNodeId: linkNodeId,
      toNodeId: subjectNodeId,
      edgeType: "source",
      label: "Explains source",
      evidenceGrade: link.postingBatch.status === LedgerPostingBatchStatus.POSTED ? "posted" : "operational",
    }))
  })

  events.forEach((event, index) => {
    const eventNodeId = `business-event-${index + 1}`
    const eventGrade: EvidenceGrade =
      event.status === BusinessEventStatus.FAILED || event.status === BusinessEventStatus.REJECTED
        ? "blocked"
        : "operational"
    nodes.push(node({
      id: eventNodeId,
      nodeType: "business.event",
      nodeId: event.id,
      label: event.eventType,
      moduleSlug: "controls",
      evidenceGrade: eventGrade,
      sourceTable: "business_events",
      available: eventGrade !== "blocked",
      redacted: false,
      metadata: { status: event.status },
    }))
    edges.push(edge({
      fromNodeId: eventNodeId,
      toNodeId: subjectNodeId,
      edgeType: eventGrade === "blocked" ? "blocks" : "source",
      label: eventGrade === "blocked" ? "Blocks trust" : "Supports operational event",
      evidenceGrade: eventGrade,
    }))
  })

  entry.auditEvents.forEach((auditEvent, index) => {
    const auditNodeId = `ledger-audit-${index + 1}`
    nodes.push(node({
      id: auditNodeId,
      nodeType: "ledger.audit_event",
      nodeId: auditEvent.id,
      label: auditEvent.message || auditEvent.action,
      moduleSlug: "controls",
      evidenceGrade: "operational",
      sourceTable: "ledger_audit_events",
      available: true,
      redacted: false,
      metadata: {
        action: auditEvent.action,
        resourceType: auditEvent.resourceType,
        resourceId: auditEvent.resourceId,
        createdAt: auditEvent.createdAt.toISOString(),
      },
    }))
    edges.push(edge({
      fromNodeId: auditNodeId,
      toNodeId: subjectNodeId,
      edgeType: "audits",
      label: "Records control event",
      evidenceGrade: "operational",
    }))
  })

  return finalizeProofTrail({
    input,
    moduleSlug: "accounting",
    decision,
    nodes,
    edges,
    blockers,
    redactions: [],
    nextActions: blockers.length
      ? [nextAction({
          id: "review-journal-entry-proof",
          label: "Review journal entry proof blockers",
          href: `/dashboard/accounting/journals`,
          requiredPermission: "accounting.journal.read",
        })]
      : [],
  }, client)
}

async function buildReconciliationRunProofTrail(input: ProofTrailInput, client: DbClient) {
  const run = await client.reconciliationRun.findFirst({
    where: { id: input.subjectId, organizationId: input.organizationId },
    include: {
      providerAccount: { select: { id: true, displayName: true, providerCode: true, status: true } },
      paymentRail: { select: { id: true, code: true, name: true } },
      matchRecords: {
        select: { id: true, status: true, confidence: true, amountMatched: true, currencyCode: true, ledgerPostingBatchId: true },
        orderBy: { createdAt: "desc" },
        take: 10,
      },
      suspenseItems: {
        select: { id: true, status: true, severity: true, amount: true, currencyCode: true },
        orderBy: { createdAt: "desc" },
        take: 10,
      },
      paymentExceptions: {
        select: { id: true, status: true, severity: true, type: true, resolutionNotes: true },
        orderBy: { createdAt: "desc" },
        take: 10,
      },
    },
  })

  if (!run) throw new NotFoundError("Reconciliation proof subject not found")

  const blockers: ProofTrailBlocker[] = []
  const { exceptions: openExceptions, suspense: openSuspense } = await paymentBlockerSummary(client, {
    organizationId: input.organizationId, reconciliationRunId: run.id,
  })

  if (run.status === ReconciliationRunStatus.FAILED || run.status === ReconciliationRunStatus.VOIDED) {
    blockers.push(createProofTrailBlocker({
      id: "reconciliation-run-failed-or-voided",
      severity: "critical",
      gate: "payments.reconciliation.status",
      title: "Reconciliation run is failed or voided",
      detail: `Run status is ${run.status}.`,
      sourceTables: ["reconciliation_runs"],
    }))
  }

  if (openExceptions.count > 0) {
    blockers.push(createProofTrailBlocker({
      id: "reconciliation-open-exceptions",
      severity: openExceptions.high ? "high" : "medium",
      gate: "payments.reconciliation.exceptions",
      title: "Open payment exceptions remain",
      detail: `${openExceptions.count} payment exception remains open or in review.`,
      sourceTables: ["payment_exceptions"],
      nextAction: "Resolve payment exceptions before relying on this reconciliation.",
    }))
  }

  if (openSuspense.count > 0) {
    blockers.push(createProofTrailBlocker({
      id: "reconciliation-open-suspense",
      severity: openSuspense.high ? "high" : "medium",
      gate: "payments.reconciliation.suspense",
      title: "Open suspense remains",
      detail: `${openSuspense.count} suspense item remains open or unresolved.`,
      sourceTables: ["suspense_items"],
      nextAction: "Resolve or post suspense before sign-off.",
    }))
  }

  if (run.status === ReconciliationRunStatus.SIGNED && !run.signedAt) {
    blockers.push(createProofTrailBlocker({
      id: "reconciliation-signed-at-missing",
      severity: "medium",
      gate: "payments.reconciliation.signoff",
      title: "Signed reconciliation timestamp is missing",
      detail: "The run is signed but does not carry signed-at evidence.",
      sourceTables: ["reconciliation_runs"],
    }))
  }

  const decision = computeReconciliationRunEvidenceGrade({
    status: run.status,
    certificateHash: run.certificateHash,
    blockers,
  })

  const subjectNodeId = "reconciliation-run"
  const redactions: ProofTrailRedaction[] = [
    createProofTrailRedaction({
      id: "provider-account-internal-id",
      field: "nodes.provider-account",
      reason: "Provider account internals are masked in the proof trail by default.",
    }),
  ]
  const nodes: ProofTrailNode[] = [
    node({
      id: subjectNodeId,
      nodeType: "reconciliation.run",
      nodeId: run.id,
      label: `Reconciliation ${run.businessDate.toISOString().slice(0, 10)}`,
      moduleSlug: "reconciliation",
      evidenceGrade: decision.grade,
      sourceTable: "reconciliation_runs",
      available: true,
      redacted: false,
      metadata: {
        status: run.status,
        matchCount: run.matchCount,
        exceptionCount: run.exceptionCount,
        suspenseAmount: money(run.suspenseAmount),
        signedAt: run.signedAt?.toISOString() ?? null,
        certificateAvailable: Boolean(run.certificateHash),
      },
    }),
    node({
      id: "provider-account",
      nodeType: "payment.provider_account",
      nodeId: run.providerAccount.id,
      label: `${run.providerAccount.providerCode} account`,
      moduleSlug: "payments",
      evidenceGrade: "operational",
      sourceTable: "provider_accounts",
      available: true,
      redacted: true,
      metadata: { status: run.providerAccount.status },
    }),
  ]
  const edges: ProofTrailEdge[] = [
    edge({
      fromNodeId: "provider-account",
      toNodeId: subjectNodeId,
      edgeType: "source",
      label: "Provides settlement evidence",
      evidenceGrade: "operational",
    }),
  ]

  run.matchRecords.forEach((matchRecord, index) => {
    const matchNodeId = `match-${index + 1}`
    const grade: EvidenceGrade =
      matchRecord.status === "APPROVED" || matchRecord.status === "AUTO_MATCHED" ? "reconciled" : "operational"
    nodes.push(node({
      id: matchNodeId,
      nodeType: "reconciliation.match",
      nodeId: matchRecord.id,
      label: `Match ${matchRecord.status}`,
      moduleSlug: "reconciliation",
      evidenceGrade: grade,
      sourceTable: "match_records",
      available: matchRecord.status !== "REJECTED" && matchRecord.status !== "VOIDED",
      redacted: false,
      metadata: {
        confidence: matchRecord.confidence.toString(),
        amountMatched: money(matchRecord.amountMatched),
        currencyCode: matchRecord.currencyCode,
        ledgerPostingBatchId: matchRecord.ledgerPostingBatchId,
      },
    }))
    edges.push(edge({
      fromNodeId: matchNodeId,
      toNodeId: subjectNodeId,
      edgeType: "matches",
      label: "Supports reconciliation result",
      evidenceGrade: grade,
    }))
  })

  run.suspenseItems.forEach((suspenseItem, index) => {
    const suspenseNodeId = `suspense-${index + 1}`
    const blocked = OPEN_SUSPENSE_STATUSES.includes(suspenseItem.status)
    nodes.push(node({
      id: suspenseNodeId,
      nodeType: "reconciliation.suspense",
      nodeId: suspenseItem.id,
      label: blocked ? "Open suspense item" : `Suspense ${suspenseItem.status}`,
      moduleSlug: "reconciliation",
      evidenceGrade: blocked ? "blocked" : "reconciled",
      sourceTable: "suspense_items",
      available: !blocked,
      redacted: false,
      metadata: {
        status: suspenseItem.status,
        severity: suspenseItem.severity,
        amount: money(suspenseItem.amount),
        currencyCode: suspenseItem.currencyCode,
      },
    }))
    edges.push(edge({
      fromNodeId: suspenseNodeId,
      toNodeId: subjectNodeId,
      edgeType: blocked ? "blocks" : "matches",
      label: blocked ? "Blocks reconciliation trust" : "Resolved suspense",
      evidenceGrade: blocked ? "blocked" : "reconciled",
    }))
  })

  run.paymentExceptions.forEach((paymentException, index) => {
    const exceptionNodeId = `exception-${index + 1}`
    const blocked = OPEN_PAYMENT_EXCEPTION_STATUSES.includes(paymentException.status)
    nodes.push(node({
      id: exceptionNodeId,
      nodeType: "payment.exception",
      nodeId: paymentException.id,
      label: blocked ? "Open payment exception" : `Payment exception ${paymentException.status}`,
      moduleSlug: "payments",
      evidenceGrade: blocked ? "blocked" : "reconciled",
      sourceTable: "payment_exceptions",
      available: !blocked,
      redacted: false,
      metadata: {
        status: paymentException.status,
        severity: paymentException.severity,
        type: paymentException.type,
      },
    }))
    edges.push(edge({
      fromNodeId: exceptionNodeId,
      toNodeId: subjectNodeId,
      edgeType: blocked ? "blocks" : "matches",
      label: blocked ? "Blocks reconciliation trust" : "Resolved exception",
      evidenceGrade: blocked ? "blocked" : "reconciled",
    }))
  })

  return finalizeProofTrail({
    input,
    moduleSlug: "reconciliation",
    decision,
    nodes,
    edges,
    blockers,
    redactions,
    nextActions: blockers.length
      ? [nextAction({
          id: "review-reconciliation-workbench",
          label: "Review reconciliation exceptions and suspense",
          href: "/dashboard/finance/reconciliation",
          requiredPermission: "payments.reconciliation.read",
        })]
      : [],
  }, client)
}

async function buildPaymentTransactionProofTrail(input: ProofTrailInput, client: DbClient) {
  const transaction = await client.paymentTransaction.findFirst({
    where: { id: input.subjectId, organizationId: input.organizationId },
    include: {
      providerAccount: {
        select: {
          id: true,
          providerCode: true,
          displayName: true,
          status: true,
          paymentRail: { select: { id: true, code: true, name: true } },
        },
      },
      ledgerPostingBatch: {
        select: {
          id: true,
          sourceType: true,
          sourceId: true,
          postingPurpose: true,
          status: true,
          errorMessage: true,
          postedAt: true,
        },
      },
      matchRecords: {
        where: { organizationId: input.organizationId },
        select: {
          id: true,
          status: true,
          confidence: true,
          amountMatched: true,
          currencyCode: true,
          ledgerPostingBatchId: true,
          providerEventId: true,
          statementLineId: true,
          reconciliationRunId: true,
        },
        orderBy: { createdAt: "desc" },
        take: 10,
      },
      suspenseItems: {
        select: { id: true, status: true, severity: true, amount: true, currencyCode: true, ledgerPostingBatchId: true },
        orderBy: { createdAt: "desc" },
        take: 10,
      },
      paymentExceptions: {
        select: { id: true, status: true, severity: true, type: true, resolutionNotes: true, suspenseItemId: true },
        orderBy: { createdAt: "desc" },
        take: 10,
      },
    },
  })

  if (!transaction) throw new NotFoundError("Payment transaction proof subject not found")

  // Display history includes proposals and rejected decisions. Only accepted
  // allocations across the complete history can establish full reconciliation.
  const matchCoverage = await client.matchRecord.groupBy({
    by: ["currencyCode"],
    where: { organizationId: input.organizationId, paymentTransactionId: transaction.id,
      status: { in: MANUAL_ALLOCATION_STATUSES } },
    _sum: { amountMatched: true }, _min: { amountMatched: true },
    _count: { _all: true, amountMatched: true },
  })
  const coverage = matchCoverage[0]
  const fullyMatched = matchCoverage.length === 1 && coverage.currencyCode === transaction.currencyCode &&
    coverage._count._all === coverage._count.amountMatched && coverage._min.amountMatched?.gt(0) === true &&
    transaction.amount.gt(0) && coverage._sum.amountMatched?.eq(transaction.amount) === true


  const eventSourceType = accountingSourceType(transaction.sourceType)
  const events = eventSourceType && transaction.sourceId
    ? await client.businessEvent.findMany({
        where: {
          organizationId: input.organizationId,
          sourceType: eventSourceType,
          sourceId: transaction.sourceId,
        },
        select: { id: true, status: true, eventType: true, failureMessage: true },
        orderBy: { recordedAt: "desc" },
        take: 10,
      })
    : []

  const { exceptions: openExceptions, suspense: openSuspense } = await paymentBlockerSummary(client, {
    organizationId: input.organizationId, paymentTransactionId: transaction.id,
  })
  const blockers: ProofTrailBlocker[] = eventSourceType && transaction.sourceId
    ? await completeEventBlockers(client, { organizationId: input.organizationId, sourceType: eventSourceType, sourceId: transaction.sourceId }, events)
    : []

  if (transaction.state === PaymentTransactionState.FAILED || transaction.state === PaymentTransactionState.CANCELLED) {
    blockers.push(createProofTrailBlocker({
      id: "payment-transaction-failed-or-cancelled",
      severity: "critical",
      gate: "payments.transaction.state",
      title: "Payment transaction failed or was cancelled",
      detail: `Payment transaction state is ${transaction.state}.`,
      sourceTables: ["payment_transactions"],
      nextAction: "Review the payment transaction before relying on this proof.",
    }))
  }

  if (transaction.state === PaymentTransactionState.DISPUTED || transaction.state === PaymentTransactionState.SUSPENSE) {
    blockers.push(createProofTrailBlocker({
      id: "payment-transaction-disputed-or-suspense",
      severity: "high",
      gate: "payments.transaction.state",
      title: "Payment transaction needs reconciliation review",
      detail: `Payment transaction state is ${transaction.state}.`,
      sourceTables: ["payment_transactions"],
      nextAction: "Resolve the dispute or suspense state in payment reconciliation.",
    }))
  }

  if (transaction.ledgerPostingBatch?.status === LedgerPostingBatchStatus.FAILED) {
    blockers.push(createProofTrailBlocker({
      id: "payment-transaction-posting-batch-failed",
      severity: "critical",
      gate: "accounting.posting-batch",
      title: "Payment posting batch failed",
      detail: transaction.ledgerPostingBatch.errorMessage || "The linked payment ledger posting batch failed.",
      sourceTables: ["ledger_posting_batches"],
    }))
  }

  if (openExceptions.count > 0) {
    blockers.push(createProofTrailBlocker({
      id: "payment-transaction-open-exceptions",
      severity: openExceptions.high ? "high" : "medium",
      gate: "payments.reconciliation.exceptions",
      title: "Open payment exceptions remain",
      detail: `${openExceptions.count} exception(s) remain open for this transaction.`,
      sourceTables: ["payment_exceptions"],
      nextAction: "Resolve payment exceptions before trusting this transaction as reconciled.",
    }))
  }

  if (openSuspense.count > 0) {
    blockers.push(createProofTrailBlocker({
      id: "payment-transaction-open-suspense",
      severity: openSuspense.high ? "high" : "medium",
      gate: "payments.reconciliation.suspense",
      title: "Open suspense remains",
      detail: `${openSuspense.count} suspense item(s) remain open for this transaction.`,
      sourceTables: ["suspense_items"],
      nextAction: "Resolve or post suspense before relying on this transaction proof.",
    }))
  }

  const decision = computePaymentTransactionEvidenceGrade({
    state: transaction.state,
    ledgerPostingBatchStatus: transaction.ledgerPostingBatch?.status,
    fullyMatched,
    blockers,
  })

  const subjectNodeId = "payment-transaction"
  const redactions: ProofTrailRedaction[] = []
  if (transaction.providerAccount) {
    redactions.push(createProofTrailRedaction({
      id: "payment-provider-account-internal-id",
      field: "nodes.provider-account",
      reason: "Provider account internals are masked in payment transaction proof trails.",
      policy: "kontava-proof-hidden-identifier-policy",
    }))
  }
  if (transaction.providerTransactionId || transaction.providerReference) {
    redactions.push(createProofTrailRedaction({
      id: "payment-provider-reference",
      field: "nodes.provider-reference",
      reason: "Provider references are protected by payment provider reference redaction policy.",
      policy: "kontava-payment-provider-reference-mask-policy",
    }))
  }

  const nodes: ProofTrailNode[] = [
    node({
      id: subjectNodeId,
      nodeType: "payment.transaction",
      nodeId: transaction.id,
      label: `Payment transaction ${transaction.id}`,
      moduleSlug: "payments",
      evidenceGrade: decision.grade,
      sourceTable: "payment_transactions",
      available: true,
      redacted: false,
      metadata: {
        state: transaction.state,
        direction: transaction.direction,
        amount: money(transaction.amount),
        feeAmount: money(transaction.feeAmount),
        currencyCode: transaction.currencyCode,
        occurredAt: transaction.occurredAt?.toISOString() ?? null,
        confirmedAt: transaction.confirmedAt?.toISOString() ?? null,
        settledAt: transaction.settledAt?.toISOString() ?? null,
        sourceType: transaction.sourceType,
        sourceId: transaction.sourceId,
        providerReferencePresent: Boolean(transaction.providerTransactionId || transaction.providerReference),
      },
    }),
  ]
  const edges: ProofTrailEdge[] = []

  if (transaction.providerAccount) {
    nodes.push(node({
      id: "provider-account",
      nodeType: "payment.provider_account",
      nodeId: transaction.providerAccount.id,
      label: `${transaction.providerAccount.providerCode} account`,
      moduleSlug: "payments",
      evidenceGrade: "operational",
      sourceTable: "provider_accounts",
      available: true,
      redacted: true,
      metadata: { status: transaction.providerAccount.status, rail: transaction.providerAccount.paymentRail.code },
    }))
    edges.push(edge({
      fromNodeId: "provider-account",
      toNodeId: subjectNodeId,
      edgeType: "source",
      label: "Provides payment rail context",
      evidenceGrade: "operational",
    }))
  }

  if (transaction.providerTransactionId || transaction.providerReference) {
    nodes.push(node({
      id: "provider-reference",
      nodeType: "payment.provider_reference",
      nodeId: transaction.providerTransactionId || transaction.providerReference || "redacted",
      label: "Provider reference",
      moduleSlug: "payments",
      evidenceGrade: "operational",
      sourceTable: "payment_transactions",
      available: true,
      redacted: true,
      metadata: undefined,
    }))
    edges.push(edge({
      fromNodeId: "provider-reference",
      toNodeId: subjectNodeId,
      edgeType: "source",
      label: "Identifies provider-side transaction",
      evidenceGrade: "operational",
    }))
  }

  if (transaction.ledgerPostingBatch) {
    const batchGrade: EvidenceGrade = transaction.ledgerPostingBatch.status === LedgerPostingBatchStatus.POSTED ? "posted" : "operational"
    nodes.push(node({
      id: "ledger-posting-batch",
      nodeType: "ledger.posting.batch",
      nodeId: transaction.ledgerPostingBatch.id,
      label: `Posting batch ${transaction.ledgerPostingBatch.postingPurpose}`,
      moduleSlug: "accounting",
      evidenceGrade: transaction.ledgerPostingBatch.status === LedgerPostingBatchStatus.FAILED ? "blocked" : batchGrade,
      sourceTable: "ledger_posting_batches",
      available: transaction.ledgerPostingBatch.status !== LedgerPostingBatchStatus.FAILED,
      redacted: false,
      metadata: {
        status: transaction.ledgerPostingBatch.status,
        sourceType: transaction.ledgerPostingBatch.sourceType,
        postedAt: transaction.ledgerPostingBatch.postedAt?.toISOString() ?? null,
      },
    }))
    edges.push(edge({
      fromNodeId: "ledger-posting-batch",
      toNodeId: subjectNodeId,
      edgeType: transaction.ledgerPostingBatch.status === LedgerPostingBatchStatus.FAILED ? "blocks" : "posts_to",
      label: transaction.ledgerPostingBatch.status === LedgerPostingBatchStatus.FAILED ? "Blocks posting proof" : "Posts payment transaction",
      evidenceGrade: transaction.ledgerPostingBatch.status === LedgerPostingBatchStatus.FAILED ? "blocked" : batchGrade,
    }))
  }

  transaction.matchRecords.forEach((matchRecord, index) => {
    const matchNodeId = `match-${index + 1}`
    const blocked = matchRecord.status === "REJECTED" || matchRecord.status === "VOIDED"
    const grade: EvidenceGrade = blocked
      ? "blocked"
      : MANUAL_ALLOCATION_STATUSES.some(status => status === matchRecord.status)
        ? "reconciled"
        : "operational"
    nodes.push(node({
      id: matchNodeId,
      nodeType: "reconciliation.match",
      nodeId: matchRecord.id,
      label: `Match ${matchRecord.status}`,
      moduleSlug: "reconciliation",
      evidenceGrade: grade,
      sourceTable: "match_records",
      available: !blocked,
      redacted: false,
      metadata: {
        confidence: matchRecord.confidence.toString(),
        amountMatched: money(matchRecord.amountMatched),
        currencyCode: matchRecord.currencyCode,
        ledgerPostingBatchId: matchRecord.ledgerPostingBatchId,
        providerEventLinked: Boolean(matchRecord.providerEventId),
        statementLineLinked: Boolean(matchRecord.statementLineId),
        reconciliationRunId: matchRecord.reconciliationRunId,
      },
    }))
    edges.push(edge({
      fromNodeId: matchNodeId,
      toNodeId: subjectNodeId,
      edgeType: blocked ? "blocks" : "matches",
      label: blocked ? "Blocks payment reconciliation" : "Matches payment transaction",
      evidenceGrade: grade,
    }))
  })

  transaction.suspenseItems.forEach((suspenseItem, index) => {
    const suspenseNodeId = `suspense-${index + 1}`
    const blocked = OPEN_SUSPENSE_STATUSES.includes(suspenseItem.status)
    nodes.push(node({
      id: suspenseNodeId,
      nodeType: "reconciliation.suspense",
      nodeId: suspenseItem.id,
      label: blocked ? "Open suspense item" : `Suspense ${suspenseItem.status}`,
      moduleSlug: "reconciliation",
      evidenceGrade: blocked ? "blocked" : "reconciled",
      sourceTable: "suspense_items",
      available: !blocked,
      redacted: false,
      metadata: {
        status: suspenseItem.status,
        severity: suspenseItem.severity,
        amount: money(suspenseItem.amount),
        currencyCode: suspenseItem.currencyCode,
        ledgerPostingBatchId: suspenseItem.ledgerPostingBatchId,
      },
    }))
    edges.push(edge({
      fromNodeId: suspenseNodeId,
      toNodeId: subjectNodeId,
      edgeType: blocked ? "blocks" : "matches",
      label: blocked ? "Blocks payment trust" : "Resolved suspense",
      evidenceGrade: blocked ? "blocked" : "reconciled",
    }))
  })

  transaction.paymentExceptions.forEach((paymentException, index) => {
    const exceptionNodeId = `exception-${index + 1}`
    const blocked = OPEN_PAYMENT_EXCEPTION_STATUSES.includes(paymentException.status)
    nodes.push(node({
      id: exceptionNodeId,
      nodeType: "payment.exception",
      nodeId: paymentException.id,
      label: blocked ? "Open payment exception" : `Payment exception ${paymentException.status}`,
      moduleSlug: "payments",
      evidenceGrade: blocked ? "blocked" : "reconciled",
      sourceTable: "payment_exceptions",
      available: !blocked,
      redacted: false,
      metadata: {
        status: paymentException.status,
        severity: paymentException.severity,
        type: paymentException.type,
        suspenseItemId: paymentException.suspenseItemId,
      },
    }))
    edges.push(edge({
      fromNodeId: exceptionNodeId,
      toNodeId: subjectNodeId,
      edgeType: blocked ? "blocks" : "matches",
      label: blocked ? "Blocks payment trust" : "Resolved exception",
      evidenceGrade: blocked ? "blocked" : "reconciled",
    }))
  })

  events.forEach((event, index) => {
    const eventNodeId = `business-event-${index + 1}`
    const eventGrade: EvidenceGrade =
      event.status === BusinessEventStatus.FAILED || event.status === BusinessEventStatus.REJECTED
        ? "blocked"
        : "operational"
    nodes.push(node({
      id: eventNodeId,
      nodeType: "business.event",
      nodeId: event.id,
      label: event.eventType,
      moduleSlug: "controls",
      evidenceGrade: eventGrade,
      sourceTable: "business_events",
      available: eventGrade !== "blocked",
      redacted: false,
      metadata: { status: event.status },
    }))
    edges.push(edge({
      fromNodeId: eventNodeId,
      toNodeId: subjectNodeId,
      edgeType: eventGrade === "blocked" ? "blocks" : "source",
      label: eventGrade === "blocked" ? "Blocks payment transaction trust" : "Supports payment transaction event",
      evidenceGrade: eventGrade,
    }))
  })

  return finalizeProofTrail({
    input,
    moduleSlug: "payments",
    decision,
    nodes,
    edges,
    blockers,
    redactions,
    nextActions: blockers.length
      ? [nextAction({
          id: "review-payment-transaction-proof",
          label: "Review payment transaction proof blockers",
          href: "/dashboard/finance/reconciliation",
          requiredPermission: "payments.reconciliation.read",
        })]
      : [],
  }, client)
}
async function buildCloseRunProofTrail(input: ProofTrailInput, client: DbClient) {
  const closeRun = await client.closeRun.findFirst({
    where: { id: input.subjectId, organizationId: input.organizationId },
    include: {
      period: { select: { id: true, name: true, status: true, startDate: true, endDate: true } },
      checklistItems: {
        select: { id: true, key: true, domain: true, status: true, severity: true, label: true, evidenceCount: true, blockerReason: true },
        orderBy: { createdAt: "asc" },
        take: 20,
      },
      findings: {
        select: { id: true, status: true, severity: true, title: true, domain: true, detail: true },
        orderBy: { createdAt: "desc" },
        take: 20,
      },
      evidenceItems: {
        select: {
          id: true,
          evidenceType: true,
          sourceTable: true,
          sourceType: true,
          sourceId: true,
          sourceLabel: true,
          provenance: true,
          available: true,
          unavailableReason: true,
        },
        orderBy: { createdAt: "desc" },
        take: 20,
      },
      packExports: {
        select: { id: true, fileType: true, watermarkId: true, isCertified: true, exportedAt: true },
        orderBy: { exportedAt: "desc" },
        take: 10,
      },
    },
  })

  if (!closeRun) throw new NotFoundError("Close proof subject not found")

  const blockers: ProofTrailBlocker[] = []
  const scope = { organizationId: input.organizationId, closeRunId: closeRun.id }
  const [findingGroups, checklistGroups, unavailableEvidenceCount, certifiedPackExportCount] = await Promise.all([
    client.closeAssuranceFinding.groupBy({
      by: ["severity"], where: { ...scope, status: { in: [...OPEN_CLOSE_FINDING_STATUSES] } }, _count: { _all: true },
    }),
    client.closeChecklistItem.groupBy({
      by: ["severity"], where: { ...scope, status: CloseChecklistStatus.FAILED }, _count: { _all: true },
    }),
    client.closeEvidenceItem.count({ where: { ...scope, available: false } }),
    client.closePackExport.count({ where: { ...scope, isCertified: true } }),
  ])
  const openFindings = severitySummary(findingGroups)
  const failedChecklistItems = severitySummary(checklistGroups)

  if (closeRun.status === CloseRunStatus.BLOCKED || closeRun.status === CloseRunStatus.VOIDED) {
    blockers.push(createProofTrailBlocker({
      id: "close-run-blocked-or-voided",
      severity: "critical",
      gate: "accounting.close.status",
      title: "Close run is blocked or voided",
      detail: `Close run status is ${closeRun.status}.`,
      sourceTables: ["close_runs"],
    }))
  }

  if (openFindings.count > 0) {
    blockers.push(createProofTrailBlocker({
      id: "close-open-findings",
      severity: openFindings.high ? "high" : "medium",
      gate: "accounting.close.findings",
      title: "Close findings remain open",
      detail: `${openFindings.count} close assurance finding remains unresolved.`,
      sourceTables: ["close_assurance_findings"],
      nextAction: "Resolve or waive open close findings before certification.",
    }))
  }

  if (failedChecklistItems.count > 0) {
    blockers.push(createProofTrailBlocker({
      id: "close-checklist-failed",
      severity: failedChecklistItems.high ? "high" : "medium",
      gate: "accounting.close.checklist",
      title: "Close checklist has failed controls",
      detail: `${failedChecklistItems.count} checklist item failed.`,
      sourceTables: ["close_checklist_items"],
    }))
  }

  if (unavailableEvidenceCount > 0) {
    blockers.push(createProofTrailBlocker({
      id: "close-evidence-unavailable",
      severity: "high",
      gate: "accounting.close.evidence",
      title: "Close evidence is unavailable",
      detail: `${unavailableEvidenceCount} close evidence item is unavailable.`,
      sourceTables: ["close_evidence_items"],
      nextAction: "Regenerate or attach the missing close evidence.",
    }))
  }

  const decision = computeCloseRunEvidenceGrade({
    status: closeRun.status,
    certifiedPackExportCount,
    blockers,
  })

  const subjectNodeId = "close-run"
  const redactions: ProofTrailRedaction[] = closeRun.packExports.length
    ? [
        createProofTrailRedaction({
          id: "close-pack-watermark",
          field: "nodes.close-pack-export-1",
          reason: "Close-pack watermark/export internals are hidden unless export permission and fresh auth pass.",
        }),
      ]
    : []
  const nodes: ProofTrailNode[] = [
    node({
      id: subjectNodeId,
      nodeType: "close.run",
      nodeId: closeRun.id,
      label: `Close run ${closeRun.period.name}`,
      moduleSlug: "close",
      evidenceGrade: decision.grade,
      sourceTable: "close_runs",
      available: true,
      redacted: false,
      metadata: {
        status: closeRun.status,
        readinessScore: closeRun.readinessScore,
        criticalBlockerCount: closeRun.criticalBlockerCount,
        highBlockerCount: closeRun.highBlockerCount,
      },
    }),
  ]
  const edges: ProofTrailEdge[] = []

  closeRun.checklistItems.forEach((item, index) => {
    const itemNodeId = `close-checklist-${index + 1}`
    const grade: EvidenceGrade = item.status === CloseChecklistStatus.FAILED ? "blocked" : "operational"
    nodes.push(node({
      id: itemNodeId,
      nodeType: "close.checklist_item",
      nodeId: item.id,
      label: item.label,
      moduleSlug: "close",
      evidenceGrade: grade,
      sourceTable: "close_checklist_items",
      available: item.status !== CloseChecklistStatus.UNAVAILABLE,
      redacted: false,
      metadata: {
        key: item.key,
        domain: item.domain,
        status: item.status,
        severity: item.severity,
        evidenceCount: item.evidenceCount,
      },
    }))
    edges.push(edge({
      fromNodeId: itemNodeId,
      toNodeId: subjectNodeId,
      edgeType: grade === "blocked" ? "blocks" : "depends_on",
      label: grade === "blocked" ? "Blocks close trust" : "Supports close readiness",
      evidenceGrade: grade,
    }))
  })

  closeRun.findings.forEach((finding, index) => {
    const findingNodeId = `close-finding-${index + 1}`
    const isOpen = OPEN_CLOSE_FINDING_STATUSES.includes(finding.status)
    nodes.push(node({
      id: findingNodeId,
      nodeType: "close.finding",
      nodeId: finding.id,
      label: finding.title,
      moduleSlug: "close",
      evidenceGrade: isOpen ? "blocked" : "operational",
      sourceTable: "close_assurance_findings",
      available: !isOpen,
      redacted: false,
      metadata: {
        status: finding.status,
        severity: finding.severity,
        domain: finding.domain,
      },
    }))
    edges.push(edge({
      fromNodeId: findingNodeId,
      toNodeId: subjectNodeId,
      edgeType: isOpen ? "blocks" : "audits",
      label: isOpen ? "Blocks close trust" : "Finding resolved or waived",
      evidenceGrade: isOpen ? "blocked" : "operational",
    }))
  })

  closeRun.evidenceItems.forEach((evidenceItem, index) => {
    const evidenceNodeId = `close-evidence-${index + 1}`
    const grade: EvidenceGrade = evidenceItem.available ? "posted" : "blocked"
    nodes.push(node({
      id: evidenceNodeId,
      nodeType: "close.evidence_item",
      nodeId: evidenceItem.id,
      label: evidenceItem.sourceLabel,
      moduleSlug: "close",
      evidenceGrade: grade,
      sourceTable: "close_evidence_items",
      available: evidenceItem.available,
      redacted: false,
      metadata: {
        evidenceType: evidenceItem.evidenceType,
        sourceTable: evidenceItem.sourceTable,
        sourceType: evidenceItem.sourceType,
        provenance: evidenceItem.provenance,
      },
    }))
    edges.push(edge({
      fromNodeId: evidenceNodeId,
      toNodeId: subjectNodeId,
      edgeType: evidenceItem.available ? "source" : "blocks",
      label: evidenceItem.available ? "Supports close evidence" : evidenceItem.unavailableReason || "Evidence unavailable",
      evidenceGrade: grade,
    }))
  })

  closeRun.packExports.forEach((packExport, index) => {
    const exportNodeId = `close-pack-export-${index + 1}`
    nodes.push(node({
      id: exportNodeId,
      nodeType: "close.pack_export",
      nodeId: packExport.id,
      label: packExport.isCertified ? "Certified close pack export" : "Draft close pack export",
      moduleSlug: "close",
      evidenceGrade: packExport.isCertified ? "certified" : "operational",
      sourceTable: "close_pack_exports",
      available: true,
      redacted: index === 0,
      metadata: {
        fileType: packExport.fileType,
        exportedAt: packExport.exportedAt.toISOString(),
      },
    }))
    edges.push(edge({
      fromNodeId: exportNodeId,
      toNodeId: subjectNodeId,
      edgeType: packExport.isCertified ? "certifies" : "source",
      label: packExport.isCertified ? "Certifies close evidence" : "Exports close pack",
      evidenceGrade: packExport.isCertified ? "certified" : "operational",
    }))
  })

  return finalizeProofTrail({
    input,
    moduleSlug: "close",
    decision,
    nodes,
    edges,
    blockers,
    redactions,
    nextActions: blockers.length
      ? [nextAction({
          id: "review-close-assurance",
          label: "Review close assurance blockers",
          href: `/dashboard/accounting/close/${closeRun.periodId}`,
          requiredPermission: "accounting.close.read",
        })]
      : [],
  }, client)
}

async function finalizeProofTrail(
  params: {
    input: ProofTrailInput
    moduleSlug: ProofTrailResult["moduleSlug"]
    decision: { grade: EvidenceGrade; reason: string }
    nodes: ProofTrailNode[]
    edges: ProofTrailEdge[]
    blockers: ProofTrailBlocker[]
    redactions: ProofTrailRedaction[]
    nextActions: ProofTrailNextAction[]
  },
  client: DbClient,
) {
  const result = applyProofTrailRedactions({
    organizationId: params.input.organizationId,
    subjectType: params.input.subjectType,
    subjectId: params.input.subjectId,
    moduleSlug: params.moduleSlug,
    evidenceGrade: params.decision.grade,
    reason: params.decision.reason,
    freshness: freshnessFor(params.blockers, params.nodes),
    generatedAt: new Date().toISOString(),
    sourceModules: sourceModules(params.nodes),
    nodes: params.nodes,
    edges: params.edges,
    blockers: params.blockers,
    redactions: params.redactions,
    nextActions: params.nextActions,
    audit: {
      accessLogged: false,
      sensitiveAccess:
        params.input.subjectType !== "journal.entry" ||
        params.decision.grade === "certified" ||
        params.redactions.length > 0,
    },
  })

  return auditSensitiveAccess(client, result, params.input.actorId)
}

export async function getProofTrail(input: ProofTrailInput, client: DbClient = db): Promise<ProofTrailResult> {
  switch (input.subjectType) {
    case "journal.entry":
      return buildJournalEntryProofTrail(input, client)
    case "reconciliation.run":
      return buildReconciliationRunProofTrail(input, client)
    case "payment.transaction":
      return buildPaymentTransactionProofTrail(input, client)
    case "close.run":
      return buildCloseRunProofTrail(input, client)
  }
}

services/evidence/evidence-grade.service:
import {
  CloseRunStatus,
  JournalEntryStatus,
  LedgerPostingBatchStatus,
  PaymentTransactionState,
  ReconciliationRunStatus,
} from "@prisma/client"

import type { EvidenceGrade, ProofTrailBlocker } from "./evidence-contracts"
import { hasBlockingProofTrailBlocker } from "./evidence-blockers.service"

export type EvidenceGradeDecision = {
  grade: EvidenceGrade
  reason: string
}

export function computeJournalEntryEvidenceGrade(input: {
  status: JournalEntryStatus
  postingBatchStatus?: LedgerPostingBatchStatus | null
  sourceLinkCount: number
  blockers: ProofTrailBlocker[]
}): EvidenceGradeDecision {
  if (hasBlockingProofTrailBlocker(input.blockers)) {
    return { grade: "blocked", reason: "Journal entry has unresolved proof blockers." }
  }

  if (input.status === JournalEntryStatus.POSTED || input.status === JournalEntryStatus.REVERSED) {
    if (input.postingBatchStatus === LedgerPostingBatchStatus.POSTED && input.sourceLinkCount > 0) {
      return { grade: "posted", reason: "Journal entry is posted and linked to a posted ledger batch." }
    }
    return { grade: "operational", reason: "Journal entry is posted but source trace is partial." }
  }

  return { grade: "raw", reason: "Journal entry exists but is not posted." }
}

export function computeReconciliationRunEvidenceGrade(input: {
  status: ReconciliationRunStatus
  certificateHash?: string | null
  blockers: ProofTrailBlocker[]
}): EvidenceGradeDecision {
  if (hasBlockingProofTrailBlocker(input.blockers)) {
    return { grade: "blocked", reason: "Reconciliation run has unresolved exceptions, suspense, or failed state." }
  }

  if (input.status === ReconciliationRunStatus.SIGNED && input.certificateHash) {
    return { grade: "certified", reason: "Reconciliation run is signed and has certificate evidence." }
  }

  if (input.status === ReconciliationRunStatus.SIGNED) {
    return { grade: "reconciled", reason: "Reconciliation run is signed." }
  }

  if (input.status === ReconciliationRunStatus.READY_FOR_SIGNOFF) {
    return { grade: "reconciled", reason: "Reconciliation run is ready for sign-off with no blocking exceptions." }
  }

  if (input.status === ReconciliationRunStatus.NEEDS_REVIEW) {
    return { grade: "operational", reason: "Reconciliation run exists but still needs review." }
  }

  return { grade: "raw", reason: "Reconciliation run has not reached review or sign-off." }
}

export function computeCloseRunEvidenceGrade(input: {
  status: CloseRunStatus
  certifiedPackExportCount: number
  blockers: ProofTrailBlocker[]
}): EvidenceGradeDecision {
  if (hasBlockingProofTrailBlocker(input.blockers)) {
    return { grade: "blocked", reason: "Close run has unresolved blockers or unavailable evidence." }
  }

  if (
    input.status === CloseRunStatus.CERTIFIED ||
    (input.status === CloseRunStatus.EXPORTED && input.certifiedPackExportCount > 0)
  ) {
    return { grade: "certified", reason: "Close run has explicit certification or certified close-pack export evidence." }
  }

  if (input.status === CloseRunStatus.READY || input.status === CloseRunStatus.EXPORTED) {
    return { grade: "operational", reason: "Close run is ready but is not certified." }
  }

  return { grade: "raw", reason: "Close run exists but is not ready for certification." }
}
export function computePaymentTransactionEvidenceGrade(input: {
  state: PaymentTransactionState
  ledgerPostingBatchStatus?: LedgerPostingBatchStatus | null
  fullyMatched: boolean
  blockers: ProofTrailBlocker[]
}): EvidenceGradeDecision {
  if (hasBlockingProofTrailBlocker(input.blockers)) {
    return { grade: "blocked", reason: "Payment transaction has unresolved proof blockers." }
  }

  if (input.fullyMatched && (input.state === PaymentTransactionState.CONFIRMED || input.state === PaymentTransactionState.SETTLED)) {
    return { grade: "reconciled", reason: "Payment transaction is matched against provider or statement evidence." }
  }

  if (input.ledgerPostingBatchStatus === LedgerPostingBatchStatus.POSTED) {
    return { grade: "posted", reason: "Payment transaction has a posted ledger batch." }
  }

  if (input.state === PaymentTransactionState.CONFIRMED || input.state === PaymentTransactionState.SETTLED) {
    return { grade: "operational", reason: "Payment transaction is confirmed but not yet reconciled." }
  }

  return { grade: "raw", reason: "Payment transaction exists but has not reached confirmation or reconciliation." }
}

